L),('113a912d-7683-40c7-a605-2e47ab21b0fb','live',NULL,'/sites/neosdemo/node-iyyapnswso4eu/node-w1v3lgv0u18gk/main/node-uj6udebcw812j','80e31411-2f59-4a93-94bd-a13ec3225d7a',25,'{\n    \"text\": \"<p>We as Neos development team have always believed that the community plays a vital role in shaping the future of the framework and CMS. Therefore, before the release, we reached out to the Neos community to understand their needs better. The team asked the community about the most requested features and the most frustrating aspects of using Neos. The response was overwhelming, with a multitude of messages pouring in. We collected all the ideas and feedback in our <a href=\\\"https:\\/\\/discuss.neos.io\\/t\\/attention-neos-community\\/6206\\\">forum<\\/a> and are excited to announce that some of these ideas will be included in this latest release. We as the Neos team would like to express our gratitude to the Neos community for the valuable feedback and ideas that helped shape the latest release and as we could not implement all the feedback for 8.3, we are looking to a bright future of new Neos releases.<\\/p>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',4,'/sites/neosdemo/node-iyyapnswso4eu/node-w1v3lgv0u18gk/main','016cab9ec3b49f25e9f0a3eccb90a4d9','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','ce17c7d45547fb4418682c083afd5cc7',NULL,'2023-04-24 19:26:57','2023-04-24 19:27:15','2023-04-24 19:27:15'),('13f81b91-ba5b-4bc6-a381-2bfd0f917ac5','live',NULL,'/sites/neosdemo/teaser','7005c7cf-4d19-ce36-0873-476b6cadb71a',250,'{}','Neos.Demo:Collection.Content.Teaser',0,0,NULL,NULL,0,'{}',14,'/sites/neosdemo','e5ea20241ea6bb2b1a36eb13100ce2ac','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','a5c067917eca93271eb74d257aaf128d',NULL,'2015-04-26 19:43:11','2019-02-04 21:20:09','2018-04-23 20:44:40'),('142bae59-7d49-47d5-8617-d17843a96755','live',NULL,'/sites/neosdemo/notfound/ma