3b-7676-e7c6-93e1-7d24a6817aaf',100,'{}','Neos.Demo:Collection.Content.Column',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/features/main/node524c37db511d4','4f8382fb47ce1ed2710d16c54ec43478','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','ce052e3e5e0770a4f68aa1ca8f79fc5a',NULL,'2015-04-26 19:43:11','2019-03-08 09:29:18',NULL),('27bcd6ee-9f76-456c-be8d-0f15f7244e1b','live',NULL,'/sites/neosdemo/teaser','7005c7cf-4d19-ce36-0873-476b6cadb71a',250,'{}','Neos.Demo:Collection.Content.Teaser',0,0,NULL,NULL,0,'{}',2,'/sites/neosdemo','e5ea20241ea6bb2b1a36eb13100ce2ac','0359ed5c416567b8bc2e5ade0f277b36','{\n    \"language\": {\n        \"0\": \"en_UK\"\n    }\n}','a5c067917eca93271eb74d257aaf128d',NULL,'2019-12-14 15:40:12','2019-12-14 15:40:33','2019-12-14 15:40:32'),('27d106d9-7395-4d9d-95be-ba17fd75de21','live',NULL,'/sites/neosdemo/features/imagetext/main','55861d58-c4e5-6121-b7cf-ef9320ebfbb0',400,'{}','Neos.Demo:Collection.Content.Main',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/features/imagetext','653e468ba5b5133603a206805c7a987a','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','e16c9883842b0bf663bf9ac0ca8cfa68',NULL,'2015-04-26 19:43:11','2022-07-20 16:52:34',NULL),('288cc769-f861-4254-ad63-16a5d3542131','live',NULL,'/sites/neosdemo/features/main/node524c37db511d4/column2/node524c390fb3cd2','0143d9ce-d20d-f7ef-39f4-910386f213eb',200,'{\n    \"text\": \"<p>If Neos was a car, <a href=\\\"https:\\/\\/flow.neos.io\\\">Flow<\\/a> were its main engine. It powers many foundational features for building extensible and adjustable&nbsp;web applications of today, such as Dependency Injection, Aspect-Oriented Programming and a unique Model-View-Controller Framework. And best of all: Everything is usable directly in Neos, should you ever need it.<\\/p><p>Flow has first-class support for Domain-Driven Design: It helps you to focus on the problem domain of your customer, shielding you from implementation details until you need them. Worried about form validation, security, file-uploads or logging? All directly built into Flow. Couple that with powerful, composer-based package management and a doctrine-based persistence layer, and you can build on the shoulders of giants.<\\/p><p>You might wonder whether it was worth to develop Flow from scratch. But if you try it out and experience the flow-feeling of development, you will see what we mean with it.<\\/p>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/features/main/node524c37db511d4/column2','0cd51880a8f5e28bfeeb477574d51487','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','45328d9a54395dde0c04b32732c313fc',NULL,'2015-04-26 19:43:11','2022-07-22 15:48:33','2022-07-22 15:48:33'),('2abeca36-ffe8-48ee-9dc7-f548f33040a2','live',NULL,'/sites/neosdemo/node-iyyapnswso4eu/node-ilusvipb5fe9x/main/node-0b7q6u5qjff06','5a743009-38af-4d81-91e8-8d6787e3cdef',50,'{}','Neos.Demo:Content.Columns.Two',0,0,NULL,NULL,0,'{}',4,'/sites/neosdemo/node-iyyapnswso4eu/node-ilusvipb5fe9x/main','5c7ad5cd09a230185e1f94fc75c2ed5b','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','b8e9342b509d1245438bd159aebafc76',NULL,'2023-03-24 15:12:37','2023-03-24 15:12:59','2023-03-24 15:12:59'),('2b8fbf18-4104-44b3-928f-3f719c3c4c39','live',NULL,'/sites/neosdemo/notfound/main','1f9645bb-53ba-ab52-43ef-e42e8dd57ff2',325,'{}','Neos.Demo:Collection.Content.Main',0,0,NULL,NULL,0,'{}',2,'/sites/neosdemo/notfound','743ddbeb2c960ff2aa50346dc0ecfe7b','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','6e6f4ac6f8bff45ca67bcaad07e13eea',NULL,'2019-03-22 17:37:13','2022-07-20 16:52:34',NULL),('2bb861e6-52f2-4a1b-af72-79b899a728f1','live',NULL,'/sites/neosdemo/features/forms/main','14d2acfe-d72f-a61b-b2b8-614158827a99',300,'{}','Neos.Demo:Collection.Content.Main',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/features/forms','45b306441ab067cdf207440d0754e6c4','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','6c2f3b518bfae477925560b4df7d6644',NULL,'2015-04-26 19:43:11','2022-07-20 16:52:34',NULL),('32fc2717-50ee-41aa-bfeb-3d5fb7292448','live',NULL,'/sites/neosdemo/main/node524a87808ab3e/column1/node524a8a4beba47','dbfd9c7d-1689-2f00-9d91-420d2a7ceb63',200,'{\n    \"text\": \"<p>The distribution of power in a city makes sure that everyone gets what they need. You don’t power a shed in the way you power a nuclear plant. The ultra-simple editing makes editors center their attention on content. If you need to add SEO data next to the content, Neos has an inspector that opens up for that kind of functionality. Just a bit more power, one step at a time...<\\/p><p>If you need more, the inspector will be expandable to the full backend screen providing the user with all the options. That’s not enough? Create custom backend modules. And if even that\'s not enough, underlying Neos, we have Flow - a first-class web framework that enables you to build web applications that integrate with your other systems.<\\/p>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/main/node524a87808ab3e/column1','1e935d09cb461db12f549acd363f9359','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','b2b99141d9b31a2666e89f6c41369f0d',NULL,'2015-04-26 19:43:11','2022-07-20 17:14:30','2022-07-20 17:14:30'),('3375a4f5-eb9b-44d8-bb72-e0466b33ba03','live',NULL,'/sites/neosdemo/features/other-elements','82c24d81-51fa-87e5-b4ec-73eb505cb826',800,'{\n    \"title\": \"Other elements\",\n    \"uriPathSegment\": \"other-elements\"\n}','Neos.Demo:Document.Page',0,0,NULL,NULL,0,'{}',11,'/sites/neosdemo/features','a26c3aceaf241d675e2950d1406b038e','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','e7b96e946836d03abe5c2015756926f3',NULL,'2015-04-26 19:43:11','2019-03-08 09:22:05',NULL),('340ac67d-9332-4bfa-8260-31c9bd1ce29a','live',NULL,'/sites/neosdemo/features/main/node524c37db511d4/column2','534c084c-4934-2199-aed3-cc0bdf1f625b',300,'{}','Neos.Demo:Collection.Content.Column',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/features/main/node524c37db511d4','45328d9a54395dde0c04b32732c313fc','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','ce052e3e5e0770a4f68aa1ca8f79fc5a',NULL,'2015-04-26 19:43:11','2019-03-08 09:29:18',NULL),('34134285-3194-4e1a-a638-da85aacf3891','live',NULL,'/sites/neosdemo/features/multiple-columns/main/node524a9dd93fdf2','fcae727b-df00-bab9-d468-3ae9f2a48ecc',500,'{\n    \"title\": \"Why, Mary Ann, what are you doing out here?\",\n    \"tagName\": \"h2\",\n    \"tagStyle\": \"h3\"\n}','Neos.Demo:Content.Headline',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/features/multiple-columns/main','4cbc1110ee46f1e0746443a9953cd8bd','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','ce3efeafd5182e2a8bca3220209b813c',NULL,'2015-04-26 19:43:11','2022-07-22 15:52:03','2022-07-22 15:52:03'),('36079fec-4f3c-4035-b658-e63be5672ca1','live',NULL,'/sites/neosdemo/features/imagetext/main/node524c186f12740/column0/node524c1878dbb26','b5c89d6d-4c3e-fac0-b3d9-4f21a1bc5e22',100,'{\n    \"text\": \"<p>Alice was beginning to get very tired of sitting by her sister on the bank, and of having nothing to do: once or twice she had peeped into the book her sister was reading, but it had no pictures or conversations in it, \\\"and what is the use of a book,\\\" thought Alice, \\\"without pictures or conversations?\\\"<\\/p><p>So she was considering in her own mind (as well as she could, for the hot day made her feel very sleepy and stupid) whether the pleasure of making a daisy-chain would be worth the trouble of getting up and picking the daisies, when suddenly a White Rabbit with pink eyes ran close by her.<\\/p>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/features/imagetext/main/node524c186f12740/column0','6a22b0e24646a5e9f8cc7f824a604842','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','27c2ddefd2dd5bc60542fc0f97cfd8cb',NULL,'2015-04-26 19:43:11','2022-07-22 15:52:44','2022-07-22 15:52:44'),('376181c2-9668-478a-941a-2d6737aed7ef','live',NULL,'/sites/neosdemo/features/custom-elements/main/node5270f5b85777b/node-s00zs4l1b6cdo','cfbe2e16-21c0-499f-a4bf-5383b1b7b626',375,'{\n    \"title\": \"This is a text only slide\",\n    \"tagName\": \"h3\"\n}','Neos.Demo:Content.Headline',0,0,NULL,NULL,0,'{}',4,'/sites/neosdemo/features/custom-elements/main/node5270f5b85777b','09661670b4f723df49e84dbfb5c821f9','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','221e4d6982d8a9d20d0c74c0dcf4ae0a',NULL,'2022-07-22 14:37:06','2022-07-22 14:37:19','2022-07-22 14:37:19'),('3c1aa77a-843b-4f50-b841-fbc9268c59a7','live',NULL,'/sites/neosdemo/features/custom-elements/main/node52a4e9bd7ec4b/column1/node52a711059a416','2dbd9143-ef3a-d76b-dd6f-2597eda93275',100,'{\n    \"text\": \"<p>With Neos it\'s easy to create custom\\n                                                    elements like a youtube video element.<\\/p>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',4,'/sites/neosdemo/features/custom-elements/main/node52a4e9bd7ec4b/column1','c215861b1407ed8926b93fae2e899092','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','e518e8523c82ecfbc392d3ea2cd18313',NULL,'2015-04-26 19:43:11','2019-02-25 17:10:06',NULL),('3c3b7e74-c9f3-4aae-8273-0958d7888a1a','live',NULL,'/sites/neosdemo/features/navigation-elements/third-item','e93e299d-5c26-34d1-44d7-526a00e1f2e2',500,'{\n    \"title\": \"Subpage #3\",\n    \"uriPathSegment\": \"subpage-no3\"\n}','Neos.Demo:Document.Page',0,0,NULL,NULL,0,'{}',11,'/sites/neosdemo/features/navigation-elements','4c910d30d41d881befc59bdf36d04fc4','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','9401859b89813486379c99e2d9d3867e',NULL,'2015-04-26 19:43:11','2019-03-08 09:22:05',NULL),('3cffce3b-47ec-4d32-a398-142be50a8bd3','live',NULL,'/sites/neosdemo/features/multiple-columns/main/node5249b021e9b20/column1/node5249b0963fad4','2a431846-fbff-26ca-d9ca-cf712506487b',100,'{\n    \"text\": \"<p>At last the Mouse, who seemed to be a\\n                                                    person of authority among them, called\\n                                                    out \\\"Sit down, all of you, and listen to me! I\'ll soon make you\\n                                                    dry enough!\\\"\\n                                                    They all sat down at once, in a large ring, with the Mouse in the\\n                                                    middle. Alice\\n                                                    kept her eyes anxiously fixed on it, for she felt sure she would\\n                                                    catch a bad\\n                                                    cold if she did not get dry very soon.\\n                                                    <\\/p>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',5,'/sites/neosdemo/features/multiple-columns/main/node5249b021e9b20/column1','db2a4745f96ec784a2e3cbd4e4595129','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','c12d6b6324ac7bd901f09b69bffb92e3',NULL,'2015-04-26 19:43:11','2019-02-25 17:10:06',NULL),('3e385e4d-1112-4640-bccb-3fade69cd273','live',NULL,'/sites/neosdemo/documentation/main/node52a7276d531e2','6fa597d6-36da-e9c9-644f-0fc9d01ae9ef',100,'{\n    \"title\": \"Documentation &amp; Support\",\n    \"tagName\": \"h1\"\n}','Neos.Demo:Content.Headline',0,0,NULL,NULL,0,'{}',8,'/sites/neosdemo/documentation/main','eba6ac7fb5115a5ab4252a2da070414b','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','cf2e081ffe15a97c97c899f20814919c',NULL,'2015-04-26 19:43:11','2022-07-22 16:03:04','2022-07-22 16:03:04'),('3e55ec77-9e16-4874-90ac-9dd3874c07cc','live',NULL,'/sites/neosdemo/features/other-elements/main/node53a18f52e9726','0c252a29-4e18-a4e6-adf7-acc272a4f41d',100,'{\n    \"title\": \"Other elements\",\n    \"tagName\": \"h1\"\n}','Neos.Demo:Content.Headline',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/features/other-elements/main','5e392ad1a9856d04e2275063e4a70e6b','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','e56bd19d773407ec7b49a0235898e7a2',NULL,'2015-04-26 19:43:11','2022-07-22 16:02:21','2022-07-22 16:02:21'),('3f30f084-f946-45ff-aec5-906362044fcb','live',NULL,'/sites/neosdemo/node-iyyapnswso4eu/node-ts7s1ssmv6m3z/main/node-l2l1sofku7oh0','2eef89a9-3679-42e3-8e59-3f8d719f6644',100,'{\n    \"text\": \"<h2>Neos UI 8.2 Highlights<\\/h2><ul><li>Pixel snapping support during crop<\\/li><li>Improvements for the Node Creation Dialog<\\/li><li>Resizable document and content trees<\\/li><li>Mark links as download with the LinkEditor<\\/li><li>A new build stack<\\/li><\\/ul>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',5,'/sites/neosdemo/node-iyyapnswso4eu/node-ts7s1ssmv6m3z/main','1ecb7f0b53048e7f6f80678ec940af74','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','7a5393269fa4f83290c8b017f7a912a8',NULL,'2023-03-24 16:59:29','2023-03-24 17:00:44','2023-03-24 17:00:44'),('41281e8d-9885-4d9e-9e31-112b4928ebe3','live',NULL,'/sites/neosdemo/features/multiple-columns/main/node524a9dc707b81/column2/node524a9e24e1127','ddc0e9b2-8279-1c8f-5960-a91ef350774d',100,'{\n    \"text\": \"<p>\\\"I wish I hadn\'t mentioned Dinah!\\\"\\n                                                    she said to herself in a\\n                                                    melancholy tone. \\\"Nobody seems to like her, down here, and I\'m\\n                                                    sure she\'s\\n                                                    the best cat in the world! Oh, my dear Dinah! I wonder if I shall\\n                                                    ever see you\\n                                                    any more!\\\" And here poor Alice began to cry again, for she felt\\n                                                    very lonely\\n                                                    and low-spirited. In a little while, however, she again heard a\\n                                                    little pattering\\n                                                    of footsteps in the distance, and she looked up eagerly, half hoping\\n                                                    that the\\n                                                    Mouse had changed his mind, and was coming back to finish his story.\\n                                                    <\\/p>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',5,'/sites/neosdemo/features/multiple-columns/main/node524a9dc707b81/column2','03e9a186ef76e9fd45e2b098949f6608','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','b5d722ccee6734a7d46f3c0b2135a098',NULL,'2015-04-26 19:43:11','2019-02-25 17:10:06',NULL),('430a1238-495c-4dd9-8c04-0489b14fa146','live',NULL,'/sites/neosdemo/features/multiple-columns/main/node524a9dc707b81/column0/node524a9e0880aa0','bade4900-afef-dc24-698a-77945917ddf1',100,'{\n    \"text\": \"<p>Alice replied eagerly, for she was always\\n                                                    ready to talk about her pet: \\\"Dinah\'s\\n                                                    our cat. And she\'s such a capital one for catching mice, you ca\'n\'t\\n                                                    think! And\\n                                                    oh, I wish you could see her after the birds! Why, she\'ll eat a\\n                                                    little bird as\\n                                                    soon as look at it!\\\"<\\/p>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',5,'/sites/neosdemo/features/multiple-columns/main/node524a9dc707b81/column0','e69ba2641c1d9b8282bef733aa89a234','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','c21c2c275dcea37b73efdc2d3ea6cfa0',NULL,'2015-04-26 19:43:11','2019-02-25 17:10:06',NULL),('4443f9f4-ea1a-4a10-8fda-40d35248fcec','live',NULL,'/sites/neosdemo/contribute/main/node-fssrso7u4t7gr','76e2ddde-3d75-4728-8640-1ccb2f7fa15c',150,'{\n    \"text\": \"<p>We welcome any kind of contribution. Translations, documentation, code, great ideas, donations and anything that makes Neos better.<\\/p><p>&nbsp;<\\/p><p>Learn more about how you can contribute to Neos CMS <a href=\\\"https:\\/\\/www.neos.io\\/community\\/participate.html\\\">here<\\/a>.<\\/p>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',25,'/sites/neosdemo/contribute/main','a85e8f7e0cdc4676d04469c9eed6776e','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','83b84aa839f9f107acb399c55d9da176',NULL,'2022-07-20 16:44:01','2022-07-20 16:46:10','2022-07-20 16:46:10'),('44cc0457-c8b3-4219-a990-26cba17f1553','live',NULL,'/sites/neosdemo/features/imagetext/main/node524c21d53285a/column0','6720f7c4-fc5b-4c68-81b0-322d681a9719',100,'{}','Neos.Demo:Collection.Content.Column',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/features/imagetext/main/node524c21d53285a','1e97f9ac45c100fe963558a2c6c0202f','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','60da23720a86846aae922b661087e79f',NULL,'2015-04-26 19:43:11','2019-03-08 09:29:18',NULL),('46a6d720-2b1b-4c1e-b53a-1de19841d730','live',NULL,'/sites/neosdemo/features/main/node524d971adfa12','86c77d6d-b704-fcb2-22fb-e2a568beeda0',300,'{}','Neos.Demo:Content.Columns.Two',0,0,NULL,NULL,0,'{}',4,'/sites/neosdemo/features/main','bf5eee874006e073e021d7e1b4a7ae9b','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','7da07e93dc8b68a639b1891c20159787',NULL,'2015-04-26 19:43:11','2019-02-25 17:17:22',NULL),('48664aea-4f69-4624-973b-62f5e64fa29e','live',NULL,'/sites/neosdemo/features/imagetext/main/node524c21d53285a/column0/node524c21dc90666','5a085bc7-5c51-39c8-62d8-90d079200f9c',100,'{\n    \"text\": \"<p>Either the well was very deep, or she fell very slowly, for she had plenty of time as she went down to look about her, and to wonder what was going to happen next. First, she tried to look down and make out what she was coming to, but it was too dark to see anything; then she looked at the sides of the well and noticed that they were filled with cupboards and book-shelves: here and there she saw maps and pictures hung upon pegs. She took down a jar from one of the shelves as she passed; it was labelled \\\"ORANGE MARMALADE,\\\" but to her disappointment it was empty; she did not like to drop the jar for fear of killing somebody underneath, so managed to put it into one of the cupboards as she fell past it.<\\/p>\",\n    \"image\": {\n        \"__flow_object_type\": \"Neos\\\\Media\\\\Domain\\\\Model\\\\ImageVariant\",\n        \"__identifier\": \"f1aed746-643b-74f4-c4e9-02a52e889f08\"\n    },\n    \"caption\": \"<p><br\\/><\\/p>\"\n}','Neos.Demo:Content.TextWithImage',0,0,NULL,NULL,0,'{}',7,'/sites/neosdemo/features/imagetext/main/node524c21d53285a/column0','4f9eda143c02890745c48f2fef67ea26','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','1e97f9ac45c100fe963558a2c6c0202f',NULL,'2015-04-26 19:43:11','2022-07-22 15:52:44','2022-07-22 15:52:44'),('486b9949-a92e-49bc-a58c-6e57f91d338f','live',NULL,'/sites/neosdemo/features/main/node524d96f6b1348/column1','39a563d5-f8a9-efe5-036d-58c0b572e97b',200,'{}','Neos.Demo:Collection.Content.Column',0,0,NULL,NULL,0,'{}',