17:38:02',NULL),('a94c462f-5bc1-4aa5-926e-b05934a6974a','live',NULL,'/sites/neosdemo/download/main/untitled','3b25cc50-ebac-66ab-7d70-e6a644f9327c',100,'{\n    \"title\": \"Download\",\n    \"tagName\": \"h1\"\n}','Neos.Demo:Content.Headline',0,0,NULL,NULL,0,'{}',7,'/sites/neosdemo/download/main','2814919ef8c7fc710a410191fe32bedf','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','bdf473f51e0bfdbf201395210372813f',NULL,'2015-04-26 19:43:10','2022-07-22 16:04:31','2022-07-22 16:04:31'),('a9a9fda7-f095-4545-997e-42c211846efe','live',NULL,'/sites/neosdemo/node-iyyapnswso4eu/node-ilusvipb5fe9x/main/node-0b7q6u5qjff06/column1/node-q80pbqzlwehjv','894bf9c7-0e20-4999-ba72-a5f007be247c',300,'{\n    \"text\": \"<h2>All Flow 8.0 Highlights<\\/h2><ul><li>Support of latest PHP versions<\\/li><li>Typed Dependency Injection<\\/li><li>Improved Caching<\\/li><li>PHP Value Object Support<\\/li><li>PSR 18 Http\\\\Client<\\/li><li>PSR 6&amp;16 Caching via CacheManager<\\/li><\\/ul>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',30,'/sites/neosdemo/node-iyyapnswso4eu/node-ilusvipb5fe9x/main/node-0b7q6u5qjff06/column1','0cc79606ef664f477f5d611843689a20','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','5af337e6fe0c7c2c14d9a74e50659969',NULL,'2023-03-24 11:11:44','2023-03-24 15:12:59','2023-03-24 15:12:59'),('aa734c52-abee-4f92-98ae-ba2c2d74078c','live',NULL,'/sites/neosdemo/features/main/node524d96f6b1348/column0/node524da24645828','de9ecb77-46df-02b2-0c71-405c9e6afd5d',200,'{\n    \"text\": \"<p>Neos can easily be extended with plugins, which are just standard packages of Flow with a little extra configuration. &nbsp;The same works for backend modules. By using convention over configuration, the required settings you need to do boils down to a minimum.<\\/p><p>Of course we know that the there\'s one thing where you need full control: The rendering of your website. In Neos, a custom package called Fusion powers the rendering process, allowing for fine-grained control over the output. No need to override complete templates or hack the source.<\\/p>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/features/main/node524d96f6b1348/column0','61a4427e2b3dc742861a0bd48f2e166d','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','0831c95e7d0104d13bcac740b6e72557',NULL,'2015-04-26 19:43:11','2022-07-22 15:48:33','2022-07-22 15:48:33'),('aa82e214-3c85-400f-a264-c3a6d8deb196','live',NULL,'/sites/neosdemo/node-iyyapnswso4eu/node-ilusvipb5fe9x/main/node-dwx5zt2gcfyfu','36c41482-4120-49bc-9413-c103205ee82d',250,'{\n    \"text\": \"<h2>Breaking Changes<\\/h2><ul><li>Raised PHP and dependency requirements<\\/li><li>Dropped support for fusion namespaces and new fusion parser<\\/li><li>Dropped support for CKEditor version 4<\\/li><\\/ul>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',16,'/sites/neosdemo/node-iyyapnswso4eu/node-ilusvipb5fe9x/main','c14471d67ab6c7552ca87ab550c12504','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','b8e9342b509d1245438bd159aebafc76',NULL,'2023-03-24 11:16:05','2023-03-24 11:18:09','2023-03-24 11:18:09'),('ab574ac2-f3aa-414d-b3c3-4e544eb74fe9','live',NULL,'/sites/neosdemo/features/main/node524d96f6b1348','e0001cd4-50b2-a390-66aa-b2e73d671f59',200,'{}','Neos.Demo:Content.Columns.Two',0,0,NULL,NULL,0,'{}',4,'/sites/neosdemo/features/main','8702d40f0cb69d459e48a12e0551ca6b','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','7da07e93dc8b68a639b1891c20159787',NULL,'2015-04-26 19:43:11','2019-02-25 17:17:22',NULL),('abebe6a8-8233-4ff4-bb0c-3562e03445c6','live',NULL,'/sites/neosdemo/contribute/main','b7d589da-4d0b-c7d9-879d-03eb83b895e4',300,'{}','Neos.Demo:Collection.Content.Main',0,0,NULL,NULL,0,'{}',7,'/sites/neosdemo/contribute','83b84aa839f9f107acb399c55d9da176','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','76c4c416d363c0f12744987e43a1bfd4',NULL,'2015-04-26 19:43:11','2022-07-20 16:52:34','2022-07-20 16:41:32'),('ae61eb10-b8fc-44ad-a339-36b4aeb1ede7','live',NULL,'/sites/neosdemo/features/imagetext/main/node524c186f12740/column1','6bce95fc-ceff-37cb-e38a-67ed1de81390',200,'{}','Neos.Demo:Collection.Content.Column',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/features/imagetext/main/node524c186f12740','1070bd3624312607b8181152f9330621','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','036667df677942db27a2f99b46877d5c',NULL,'2015-04-26 19:43:11','2019-03-08 09:29:18',NULL),('af385825-43c3-4442-a5b8-7401eb1c5db1','live',NULL,'/sites/neosdemo/main/node524a87808ab3e/column0/node524a8a41c2f1f','5f055aca-616a-dd77-112b-3c45d1b591fb',200,'{\n    \"text\": \"<p>In only a few years from now, the world will have entirely new cities. Cities where development has not even started. Cities that can draw from all we know about liveability and functionality.<\\/p><p>The same goes for websites. Major websites will be built with the tools we’re constructing today. But we don\'t know how they will be like. Just think of how different sites were 3 years ago. For both cities and websites, one basic rule counts: Things are constantly changing and can never be fully anticipated.<\\/p><p>The inspiration from urban planning permeates our UX master plan, giving us crucial guidelines for structuring everything we know &nbsp;- and making room for all the future change we don’t know.&nbsp;<\\/p>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/main/node524a87808ab3e/column0','1f8ec7e2ce77c91eb9a73f4598088850','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','c99f32925e9dfd1d07767989f6c29faf',NULL,'2015-04-26 19:43:11','2022-07-20 17:14:30','2022-07-20 17:14:30'),('af4bd955-a5e8-4b3d-91e0-b23bfafcc745','live',NULL,'/','9b3fa55b-b9ed-4bea-8b33-7d11eb01162b',NULL,'{}','unstructured',0,0,NULL,NULL,0,'{}',1,'','6666cd76f96956469e7be39d750cc7d9','d751713988987e9331980363e24189ce','{}','d41d8cd98f00b204e9800998ecf8427e',NULL,'2026-09-30 11:22:40','2026-09-30 11:22:40',NULL),('b10d1c8f-5300-4b72-86b3-4191f6f8e3bc','live',NULL,'/sites/neosdemo/node-iyyapnswso4eu/node-ts7s1ssmv6m3z/main/node-rvuo58wym8kew/column1/node-q80pbqzlwehjv','4ef251de-6040-4cc0-a136-98fc8353aa16',300,'{\n    \"text\": \"<h2>Flow 8.2 Highlights<\\/h2><ul><li>Cache multi backend improvements<\\/li><li>Static functions in compiled EEL<\\/li><\\/ul>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',7,'/sites/neosdemo/node-iyyapnswso4eu/node-ts7s1ssmv6m3z/main/node-rvuo58wym8kew/column1','4abbd1a5e2e6c47d335304de36be3c58','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','afdd1054231dc7855d54f078b7261f19',NULL,'2023-03-24 16:58:01','2023-03-24 17:00:04','2023-03-24 17:00:04'),('b131f21c-4807-42b1-8fb0-acb33583760b','live',NULL,'/sites/neosdemo/main','b189bfaa-080c-96da-6cb9-f32bbc0b41b1',269,'{}','Neos.Demo:Collection.Content.Main',0,0,NULL,NULL,0,'{}',15,'/sites/neosdemo','35390fe0d8755802290753862b2026a5','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','a5c067917eca93271eb74d257aaf128d',NULL,'2015-04-26 19:43:11','2022-07-20 16:52:34','2018-04-23 20:44:40'),('b1504173-a346-4fa3-b926-bbaf4f10b61f','live',NULL,'/sites/neosdemo/node-iyyapnswso4eu/teaser','32457b73-b7b4-5e32-5d49-90c3b1dfc8d2',100,'{}','Neos.Demo:Collection.Content.Teaser',0,0,NULL,NULL,0,'{}',2,'/sites/neosdemo/node-iyyapnswso4eu','c38cddabbdeb850150f7b94dfbd0efed','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','6f19dab875da61f04df4256255bd86ba',NULL,'2023-03-24 10:17:00','2023-03-24 10:53:47','2023-03-24 10:53:47'),('b1f1ac0b-7d49-4a9b-bb47-255fadea0472','live',NULL,'/sites/neosdemo/features/main','b29a8d8f-5bbe-975f-b403-350c3a27e3a5',550,'{}','Neos.Demo:Collection.Content.Main',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/features','7da07e93dc8b68a639b1891c20159787','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','e7b96e946836d03abe5c2015756926f3',NULL,'2015-04-26 19:43:11','2022-07-20 16:52:34',NULL),('b20a7c43-f423-405d-a162-68859966e475','live',NULL,'/sites/neosdemo/main/node524a87808ab3e/column0','0f971681-654f-7bbf-7faa-c1d33dd4431d',100,'{}','Neos.Demo:Collection.Content.Column',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/main/node524a87808ab3e','c99f32925e9dfd1d07767989f6c29faf','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','ad79131875666d8c7d916bdf3c897692',NULL,'2015-04-26 19:43:11','2019-03-08 09:29:18',NULL),('b2815432-f53d-4378-84a4-a660ab819cb0','live',NULL,'/sites/neosdemo/features/custom-elements/main/node52a723c19772a','b122ee6e-d595-c3cf-50a6-c7369e6e5c5b',200,'{\n    \"title\": \"Javascript carousel\",\n    \"tagName\": \"h2\"\n}','Neos.Demo:Content.Headline',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/features/custom-elements/main','33a27d01fcf88ab858f4871cf1ab5903','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','33716e39ea525df08730a00cbc4f18f8',NULL,'2015-04-26 19:43:11','2022-07-22 15:54:57','2022-07-22 15:54:57'),('b80e7652-3221-4b01-97d5-6abcda084f7c','live',NULL,'/sites/neosdemo/node-iyyapnswso4eu/node-ilusvipb5fe9x/main/node-0b7q6u5qjff06/column0','10aeb2d7-8cec-b3dd-0f75-2edf5cf2de1d',100,'{}','Neos.Demo:Collection.Content.Column',0,0,NULL,NULL,0,'{}',2,'/sites/neosdemo/node-iyyapnswso4eu/node-ilusvipb5fe9x/main/node-0b7q6u5qjff06','f50aa3eea75b8197569a9ce774214bd2','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','5c7ad5cd09a230185e1f94fc75c2ed5b',NULL,'2023-03-24 15:12:37','2023-03-24 15:12:59','2023-03-24 15:12:59'),('b82ed671-71a4-4f24-b3ad-9a6482bb2f50','live',NULL,'/sites/neosdemo/footer','037aba4f-10c1-a349-e816-352f11ad2f22',1100,'{}','Neos.Demo:Collection.Content.Footer',0,0,NULL,NULL,0,'{}',3,'/sites/neosdemo','72445d94e411957ef161b9aa18e630c6','0359ed5c416567b8bc2e5ade0f277b36','{\n    \"language\": {\n        \"0\": \"en_UK\"\n    }\n}','a5c067917eca93271eb74d257aaf128d',NULL,'2019-12-14 15:40:12','2022-07-20 16:35:25','2019-12-14 15:40:32'),('ba2033d8-52ca-422b-8d10-290a957083b4','live',NULL,'/sites/neosdemo/features/multiple-columns/main/node5249b021e9b20/column0/node5249b0794117a','2222f152-129a-fd14-bcdc-0eadca990d90',100,'{\n    \"text\": \"<p>The first question of course was, how to\\n                                                    get dry again: they had a\\n                                                    consultation about this, and after a few minutes it seemed quite\\n                                                    natural to\\n                                                    Alice to find herself talking familiarly with them, as if she had\\n                                                    known them all\\n                                                    her life. Indeed, she had quite a long argument with the Lory, who\\n                                                    at last\\n                                                    turned sulky, and would only say, \\\"I am older than you, and\\n                                                    must know\\n                                                    better;\\\" and this Alice would not allow without knowing how old\\n                                                    it was,\\n                                                    and, as the Lory positively refused to tell its age, there was no\\n                                                    more to be\\n                                                    said.\\n                                                    <\\/p>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',5,'/sites/neosdemo/features/multiple-columns/main/node5249b021e9b20/column0','516e4081b16b8baa767356628704c15c','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','35cd0b9db882e09da751d7e5c244976a',NULL,'2015-04-26 19:43:11','2019-02-25 17:10:06',NULL),('bc24e07e-a4da-4db6-9e39-1427b9ac76c1','live',NULL,'/sites/neosdemo/main','b189bfaa-080c-96da-6cb9-f32bbc0b41b1',325,'{}','Neos.Demo:Collection.Content.Main',0,0,NULL,NULL,0,'{}',3,'/sites/neosdemo','35390fe0d8755802290753862b2026a5','0359ed5c416567b8bc2e5ade0f277b36','{\n    \"language\": {\n        \"0\": \"en_UK\"\n    }\n}','a5c067917eca93271eb74d257aaf128d',NULL,'2019-12-14 15:40:12','2022-07-20 16:52:34','2019-12-14 15:40:32'),('bd026632-7568-4ada-bc99-a7a74269c545','live',NULL,'/sites/neosdemo/teaser','7005c7cf-4d19-ce36-0873-476b6cadb71a',250,'{}','Neos.Demo:Collection.Content.Teaser',0,0,NULL,NULL,0,'{}',5,'/sites/neosdemo','e5ea20241ea6bb2b1a36eb13100ce2ac','fb11fdde869d0a8fcfe00a2fd35c031d','{\n    \"language\": {\n        \"0\": \"de\"\n    }\n}','a5c067917eca93271eb74d257aaf128d',NULL,'2015-07-31 19:04:57','2019-02-04 21:20:09','2018-04-20 21:12:52'),('bd3f3a10-0e1b-41f7-b4b9-82b9ed522f54','live',NULL,'/sites/neosdemo/features/multiple-columns/main/node524a9d2ab69b0/column1','0971d5ac-40c4-4158-4151-be12a5e5cd29',200,'{}','Neos.Demo:Collection.Content.Column',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/features/multiple-columns/main/node524a9d2ab69b0','1973e0a32ab1970e7511d49b22dc67f5','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','ddbe20e51667dc55c85eb5623078bb56',NULL,'2015-04-26 19:43:11','2019-03-08 09:29:18',NULL),('bf955ea9-3a0d-4398-826c-b0c752c9f9bf','live',NULL,'/sites/neosdemo/node-iyyapnswso4eu/node-w1v3lgv0u18gk/main/node-rvuo58wym8kew/column1/node-q80pbqzlwehjv','653eec4f-7c75-4f02-87a0-3d3e43706840',300,'{\n    \"text\": \"<h2>Flow 8.3 Highlights<\\/h2><ul><li>Adding cache lifetime to routing MatchResult and ResolveResult DTOs<\\/li><li>New validators MediaType, FileExtension and FileSize<\\/li><\\/ul>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',7,'/sites/neosdemo/node-iyyapnswso4eu/node-w1v3lgv0u18gk/main/node-rvuo58wym8kew/column1','6fddcb4d4a54a819f6b55744fb2d6663','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','d72e12e3995bb7afc247a30ea7c39d4d',NULL,'2023-04-24 09:52:00','2023-04-24 10:13:37','2023-04-24 10:13:37'),('c0f2a44c-724f-4ed4-a244-a65c70d4d5ec','live',NULL,'/sites/neosdemo/features/imagetext/main/node524c186f12740/column1/node524c18b107a6a','26c92b43-cf7e-f6e8-a329-1f360005127c',100,'{\n    \"text\": \"<p>There was nothing so very remarkable in\\n                                                    that; nor did Alice think it so very\\n                                                    much out of the way to hear the Rabbit say to itself, \\\"Oh dear!\\n                                                    Oh dear! I\\n                                                    shall be too late!\\\" (when she thought it over afterwards, it\\n                                                    occurred to\\n                                                    her that she ought to have wondered at this, but at the time it all\\n                                                    seemed quite\\n                                                    natural); but when the Rabbit actually took a watch out of its\\n                                                    waistcoat-pocket,\\n                                                    and looked at it, and then hurried on, Alice started to her feet,\\n                                                    for it flashed\\n                                                    across her mind that she had never before seen a rabbit with either\\n                                                    a\\n                                                    waistcoat-pocket, or a watch to take out of it, and burning with\\n                                                    curiosity, she\\n                                                    ran across the field after it, and was just in time to see it pop\\n                                                    down a large\\n                                                    rabbit-hole under the hedge.\\n                                                    <\\/p>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',5,'/sites/neosdemo/features/imagetext/main/node524c186f12740/column1','d5e043e47283fd48fc8be25dbee1d219','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','1070bd3624312607b8181152f9330621',NULL,'2015-04-26 19:43:11','2019-02-25 17:10:06',NULL),('c109a829-f7ec-46b8-b865-a9c75c33350f','live',NULL,'/sites/neosdemo/contribute','2d26b296-d3d2-69c1-b73e-0d1c801fe07a',675,'{\n    \"title\": \"Contribute\",\n    \"uriPathSegment\": \"contribute\"\n}','Neos.Demo:Document.Page',0,0,NULL,NULL,1,'{}',12,'/sites/neosdemo','76c4c416d363c0f12744987e43a1bfd4','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','a5c067917eca93271eb74d257aaf128d',NULL,'2015-04-26 19:43:11','2022-07-20 16:41:32','2022-07-20 16:41:32'),('c3292745-9708-4d83-b304-841a2b0337af','live',NULL,'/sites/neosdemo/features/navigation-elements/first-item','7c3e4946-d216-14d0-92c5-d7fa75163863',300,'{\n    \"title\": \"Subpage #1\",\n    \"uriPathSegment\": \"subpage-no1\"\n}','Neos.Demo:Document.Page',0,0,NULL,NULL,0,'{}',11,'/sites/neosdemo/features/navigation-elements','a3056cd04c467db0e86182d19ebbccee','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','9401859b89813486379c99e2d9d3867e',NULL,'2015-04-26 19:43:11','2019-03-08 09:22:05',NULL),('c37948ce-f38c-4b4a-91b4-7082e47fa038','live',NULL,'/sites/neosdemo/footer','037aba4f-10c1-a349-e816-352f11ad2f22',1350,'{}','Neos.Demo:Collection.Content.Footer',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo','72445d94e411957ef161b9aa18e630c6','fb11fdde869d0a8fcfe00a2fd35c031d','{\n    \"language\": {\n        \"0\": \"de\"\n    }\n}','a5c067917eca93271eb74d257aaf128d',NULL,'2015-07-31 19:04:57','2022-07-20 16:35:25','2018-04-20 21:12:52'),('c528862b-06a4-454a-8770-f9906fc4d915','live',NULL,'/sites/neosdemo/features/main/node524d971adfa12/column1/node524dac5b2fe75','fc42beed-baea-2b08-32ad-255bc53ee366',100,'{\n    \"title\": \"Fire It Up for a Test Drive\",\n    \"tagName\": \"h2\",\n    \"tagStyle\": \"h4\"\n}','Neos.Demo:Content.Headline',0,0,NULL,NULL,0,'{}',6,'/sites/neosdemo/features/main/node524d971adfa12/column1','112f0fe78d85f61ba719420bea9ec549','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','eb75d21fe2109eecb17d2d68665cde80',NULL,'2015-04-26 19:43:11','2022-07-22 15:49:51','2022-07-22 15:49:51'),('c550a0da-4dcc-4a76-9618-9846b331d94b','live',NULL,'/sites/neosdemo/node-iyyapnswso4eu/main','c1551ec9-cf56-ecba-dd94-950447a6f75d',200,'{}','Neos.Demo:Collection.Content.Main',0,0,NULL,NULL,0,'{}',2,'/sites/neosdemo/node-iyyapnswso4eu','6d6fde32678b291763853553d9f183f0','4f534b1eb0c1a785da31e681fb5e91ff','{\n    \"language\": {\n        \"0\": \"en_US\"\n    }\n}','6f19dab875da61f04df4256255bd86ba',NULL,'2023-03-24 10:17:00','2023-03-24 10:53:47','2023-03-24 10:53:47'),('c65995e9-bd21-4359-ba7d-b37b3374aefe','live',NULL,'/sites/neosdemo/node-iyyapnswso4eu/node-77zozlu9y302j/main/node-in3brxjx32qo8/column1/node-q80pbqzlwehjv','b54573bc-34ff-41bb-972a-d53e4da4b8a2',300,'{\n    \"text\": \"<h2>Flow 8.1 Highlights<\\/h2><ul><li>Typed environment variable replacements in Settings<\\/li><li>Support for object serialization without var annotation<\\/li><\\/ul>\"\n}','Neos.Demo:Content.Text',0,0,NULL,NULL,0,'{}',10,'/sites/neosdemo/node-iyyapnswso4eu/node-77zozlu9y302j/main/node-in3brxjx32qo8/column1','5755fee54f8e5b656120fe9c0c8a983b','4f534b1eb0c1a785da